package com.aiot.log.controller;
import com.aiot.log.common.ApiResponse; import com.aiot.log.config.EnvironmentProperties; import com.aiot.log.dto.EnvironmentWeatherConfigRequest; import com.aiot.log.exception.*; import com.aiot.log.vo.EnvironmentWeatherConfigVO; import jakarta.annotation.PostConstruct; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.nio.file.*; import java.io.*; import java.util.Properties;
@RestController @RequestMapping("/api/environment-weather-config") public class EnvironmentWeatherConfigController { final EnvironmentProperties p; final Path pem, config; public EnvironmentWeatherConfigController(EnvironmentProperties p,@Value("${IOT_CONFIG_DIR:}") String dir){this.p=p; Path base=Path.of(dir==null||dir.isBlank()?"config":dir);this.pem=base.resolve("qweather-ed25519-private.pem");this.config=base.resolve("environment-weather.properties");} @PostConstruct public void load(){try{if(!Files.isRegularFile(config))return;Properties x=new Properties();try(InputStream in=Files.newInputStream(config)){x.load(in);}p.setEnabled(true);p.setApiHost(x.getProperty("apiHost",""));p.setJwtKid(x.getProperty("jwtKid",""));p.setJwtProjectId(x.getProperty("jwtProjectId",""));p.setJwtPrivateKeyFile(pem.toAbsolutePath().toString());}catch(Exception ignored){}} @GetMapping public ApiResponse<EnvironmentWeatherConfigVO> get(){EnvironmentWeatherConfigVO v=new EnvironmentWeatherConfigVO();v.apiHost=p.getApiHost();v.jwtKid=p.getJwtKid();v.jwtProjectId=p.getJwtProjectId();v.privateKeyConfigured=Files.isRegularFile(pem);v.configured=p.isConfigured();return ApiResponse.success(v);} @PutMapping public synchronized ApiResponse<EnvironmentWeatherConfigVO> save(@Valid @RequestBody EnvironmentWeatherConfigRequest r){try{Files.createDirectories(pem.getParent());if(r.privateKeyPem!=null&&!r.privateKeyPem.isBlank()){if(!r.privateKeyPem.contains("BEGIN PRIVATE KEY"))throw new BusinessException(ErrorCode.REQUEST_VALIDATION_FAILED,"私钥必须是 PEM 格式");Files.writeString(pem,r.privateKeyPem.trim()+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING); } if(!Files.isRegularFile(pem))throw new BusinessException(ErrorCode.REQUEST_VALIDATION_FAILED,"请首次填写 PEM 私钥");Properties x=new Properties();x.setProperty("apiHost",r.apiHost.trim().replaceFirst("^https?://","").replaceAll("/$",""));x.setProperty("jwtKid",r.jwtKid.trim());x.setProperty("jwtProjectId",r.jwtProjectId.trim());try(OutputStream out=Files.newOutputStream(config)){x.store(out,"Private weather configuration. Do not commit or share.");}p.setEnabled(true);p.setApiHost(x.getProperty("apiHost"));p.setJwtKid(x.getProperty("jwtKid"));p.setJwtProjectId(x.getProperty("jwtProjectId"));p.setJwtPrivateKeyFile(pem.toAbsolutePath().toString());return get();}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(ErrorCode.INTERNAL_ERROR,"保存天气私有配置失败");}} }
